import React from "react";
import "./Gallery.css";

const galleryImages = [
{ title: "Home Cleaning", img: "[https://images.unsplash.com/photo-1581579188871-45ea61f2a0c8?w=800](https://images.unsplash.com/photo-1581579188871-45ea61f2a0c8?w=800)" },
{ title: "Gardening", img: "[https://images.unsplash.com/photo-1501004318641-b39e6451bec6?w=800](https://images.unsplash.com/photo-1501004318641-b39e6451bec6?w=800)" },
{ title: "Plumbing Work", img: "[https://images.unsplash.com/photo-1563453392212-326f5e854473?w=800](https://images.unsplash.com/photo-1563453392212-326f5e854473?w=800)" }
// add the rest of your images here
];

export default function Gallery() {
return ( <div className="gallery-container"> <h2 className="gallery-title">Gallery</h2> <div className="gallery-grid">
{galleryImages.map((item, index) => ( <div className="gallery-card" key={index}> <img src={item.img} alt={item.title} /> <p>{item.title}</p> </div>
))} </div> </div>
);
}
